'use strict';

const KEY_RE = /^[A-Z][A-Z0-9_]*$/;
const INT_RE = /^(?:0|[1-9][0-9]*)$/;

// Known fields in schema order. Only COLOR is a recognized optional field.
const INTEGER_FIELDS = [
  ['WINDOW', 1, 50],
  ['RATE', 0, 30],
  ['LIMIT', 1, 25],
];
const COLOR_VALUES = ['white', 'black'];

function formatError() {
  return new Error('INVALID_FORMAT');
}

function valueError() {
  return new Error('INVALID_VALUE');
}

function isRecordEnd(ch) {
  return ch === '\n' || ch === '\r';
}

// Reads one record starting at `pos`. Returns { fields, next } where `next`
// is the index just past the record terminator (or text.length).
function readRecord(text, pos) {
  const fields = [];
  let i = pos;
  for (;;) {
    let field = '';
    if (text[i] === '"') {
      i++;
      let closed = false;
      while (i < text.length) {
        const ch = text[i];
        if (ch === '"') {
          if (text[i + 1] === '"') {
            field += '"';
            i += 2;
          } else {
            i++;
            closed = true;
            break;
          }
        } else {
          field += ch;
          i++;
        }
      }
      if (!closed) throw formatError();
      if (i < text.length && text[i] !== ';' && !isRecordEnd(text[i])) {
        throw formatError();
      }
    } else {
      while (i < text.length && text[i] !== ';' && !isRecordEnd(text[i])) {
        if (text[i] === '"') throw formatError();
        field += text[i];
        i++;
      }
    }
    fields.push(field);

    if (i >= text.length) return { fields, next: i };
    if (text[i] === ';') {
      i++;
      continue;
    }
    // Record terminator: CRLF, CR, or LF.
    if (text[i] === '\r' && text[i + 1] === '\n') i += 2;
    else i += 1;
    return { fields, next: i };
  }
}

function decodeFields(rawFields) {
  const values = new Map();
  for (const raw of rawFields) {
    const eq = raw.indexOf('=');
    if (eq === -1 || raw.indexOf('=', eq + 1) !== -1) throw formatError();
    const key = raw.slice(0, eq);
    if (!KEY_RE.test(key)) throw formatError();
    if (values.has(key)) throw formatError();
    values.set(key, raw.slice(eq + 1).trim());
  }
  return values;
}

function buildRecord(values) {
  const out = {};
  for (const [key, min, max] of INTEGER_FIELDS) {
    if (!values.has(key)) throw valueError();
    const str = values.get(key);
    if (!INT_RE.test(str)) throw valueError();
    const num = Number(str);
    if (num < min || num > max) throw valueError();
    Object.defineProperty(out, key, {
      value: num, enumerable: true, writable: true, configurable: true,
    });
  }
  if (values.has('COLOR')) {
    const color = values.get('COLOR');
    if (!COLOR_VALUES.includes(color)) throw valueError();
    Object.defineProperty(out, 'COLOR', {
      value: color, enumerable: true, writable: true, configurable: true,
    });
  }
  // Unknown keys are dropped after syntax and duplicate validation.
  return out;
}

function parseBundle(text) {
  if (typeof text !== 'string') throw formatError();
  if (text === '') return [];

  const result = [];
  let pos = 0;
  while (pos < text.length) {
    const { fields, next } = readRecord(text, pos);
    // Syntax and duplicate validation for this record first, then semantics.
    const values = decodeFields(fields);
    result.push(buildRecord(values));
    pos = next;
  }
  return result;
}

module.exports = { parseBundle };
